namespace SmartInventory.Core.DTOs;

/// <summary>One cart line sent by the POS. The price is deliberately NOT part of the request: the server decides it.</summary>
public record CartItemDto(Guid ProductId, int Quantity);

/// <param name="SaleId">
/// Optional idempotency key generated by the client for one checkout attempt. If the network drops after the
/// server committed, the client retries with the SAME id and the server refuses to record the sale twice.
/// </param>
public record CheckoutRequestDto(IReadOnlyList<CartItemDto> Items, Guid? SaleId = null);

/// <summary>Machine-readable reasons a checkout can fail. The POS UI switches on these.</summary>
public static class CheckoutErrorCodes
{
    public const string Invalid = "invalid";
    public const string NotFound = "not_found";
    public const string InsufficientStock = "insufficient_stock";
    public const string Duplicate = "duplicate";
}

/// <param name="Available">Set for insufficient_stock: how many units can still be sold right now.</param>
public record CheckoutErrorDto(string Code, string Message, Guid? ProductId = null, int? Available = null);

/// <param name="RemainingStock">Stock after this sale — lets the POS refresh its tiles without a reload.</param>
/// <param name="IsLowStock">True when RemainingStock is at or below the reorder level (the level itself is never sent to cashiers).</param>
public record CheckoutLineDto(
    Guid ProductId,
    string Sku,
    string Name,
    int Quantity,
    decimal UnitPrice,
    decimal LineTotal,
    int RemainingStock,
    bool IsLowStock);

public record CheckoutResultDto(
    bool Success,
    string? ReceiptNumber,
    decimal GrandTotal,
    IReadOnlyList<CheckoutLineDto> Lines,
    IReadOnlyList<CheckoutErrorDto> Errors)
{
    public static CheckoutResultDto Failed(params CheckoutErrorDto[] errors) =>
        new(false, null, 0m, [], errors);

    public static CheckoutResultDto Failed(IReadOnlyList<CheckoutErrorDto> errors) =>
        new(false, null, 0m, [], errors);
}
